"""Report content assembly (shared by JSON and PDF renderers).

Each section is tagged with its provenance so readers can distinguish:
* ``observed``    , data received from the SIEM (first-party observation);
* ``third_party`` , information reported by OSINT / threat-intelligence sources;
* ``computed``    , deterministic computations (correlation, scoring);
* ``ai_generated``, content generated by the AI module (LLM or rule engine).
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.core.config import APP_VERSION, get_settings
from app.core.timeutil import iso, utc_now
from app.investigation.queries import current_results
from app.models import AIAnalysis, EnrichmentResult, IndicatorRelation, Investigation, InvestigationIndicator, InvestigationNote

REPORT_SCHEMA_VERSION = "1.0"


def latest_analysis(db: Session, inv_id: str) -> AIAnalysis | None:
    return db.scalars(
        select(AIAnalysis).where(AIAnalysis.investigation_id == inv_id).order_by(AIAnalysis.id.desc()).limit(1)
    ).first()


def build_timeline(db: Session, inv: Investigation) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for e in inv.events:
        items.append({"ts": iso(e.event_time or e.received_at), "kind": "siem_event", "provenance": "observed",
                      "label": f"{e.title} ({e.severity})", "detail": f"{e.source_system}:{e.original_id}",
                      "is_synthetic": e.is_synthetic})
        items.append({"ts": iso(e.received_at), "kind": "ingested", "provenance": "computed",
                      "label": f"Événement ingéré ({e.ingest_method})", "detail": e.original_id, "is_synthetic": e.is_synthetic})
    for r in db.scalars(select(EnrichmentResult).where(EnrichmentResult.investigation_id == inv.id)):
        items.append({"ts": iso(r.queried_at), "kind": "osint_query", "provenance": "third_party",
                      "label": f"{r.source_name} : {r.status} (passe {r.run_number}{', remplacée' if r.superseded_at else ''})", "detail": r.indicator.value, "is_synthetic": r.is_synthetic})
    for a in db.scalars(select(AIAnalysis).where(AIAnalysis.investigation_id == inv.id)):
        items.append({"ts": iso(a.created_at), "kind": "ai_analysis", "provenance": "ai_generated",
                      "label": f"Analyse {a.provider} : {a.status}", "detail": a.model or "", "is_synthetic": False})
    for n in db.scalars(select(InvestigationNote).where(InvestigationNote.investigation_id == inv.id)):
        items.append({"ts": iso(n.created_at), "kind": f"analyst_{n.kind}", "provenance": "observed",
                      "label": f"{n.kind}, {n.user.username if n.user else 'système'}", "detail": n.content[:300],
                      "is_synthetic": False})
    return sorted(items, key=lambda i: i["ts"] or "")


def build_report_data(db: Session, inv: Investigation, kind: str, generated_by: str) -> dict[str, Any]:
    links = list(db.scalars(select(InvestigationIndicator).where(InvestigationIndicator.investigation_id == inv.id)))
    results = current_results(db, inv.id)
    relations = list(db.scalars(select(IndicatorRelation).where(IndicatorRelation.investigation_id == inv.id)))
    analysis = latest_analysis(db, inv.id)
    notes = list(db.scalars(select(InvestigationNote).where(InvestigationNote.investigation_id == inv.id).order_by(InvestigationNote.id)))
    synthetic = inv.is_synthetic or any(r.is_synthetic for r in results)
    data: dict[str, Any] = {
        "schema_version": REPORT_SCHEMA_VERSION,
        "report_kind": kind,
        "generator": {"application": get_settings().app_name, "version": APP_VERSION},
        "generated_at": iso(utc_now()),
        "generated_by": generated_by,
        "contains_synthetic_data": synthetic,
        "investigation": {
            "id": inv.id, "reference": inv.reference, "title": inv.title, "status": inv.status, "priority": inv.priority,
            "severity": inv.severity, "created_at": iso(inv.created_at), "updated_at": iso(inv.updated_at),
            "pipeline_status": inv.pipeline_status,
        },
        "alert_context": {
            "provenance": "observed",
            "events": [{
                "source_system": e.source_system, "original_id": e.original_id, "event_time": iso(e.event_time),
                "received_at": iso(e.received_at), "ingest_method": e.ingest_method, "title": e.title,
                "event_type": e.event_type, "severity": e.severity, "severity_raw": e.severity_raw,
                "src_ip": e.src_ip, "dst_ip": e.dst_ip, "src_port": e.src_port, "dst_port": e.dst_port,
                "protocol": e.protocol, "hostname": e.hostname, "attempt_count": e.attempt_count,
                "raw_sha256": e.raw_sha256, "is_synthetic": e.is_synthetic,
            } for e in inv.events],
        },
        "indicators": [{
            "type": l.indicator.type, "value": l.indicator.value, "role": l.role, "scope": l.indicator.scope,
            "note": l.indicator.classification.get("note"), "extracted_from": l.extracted_from,
        } for l in links],
        "osint_results": {
            "provenance": "third_party",
            "items": [{
                "evidence_id": f"R{r.id}", "source": r.source_name, "indicator": r.indicator.value, "status": r.status,
                "queried_at": iso(r.queried_at), "data_updated_at": iso(r.data_updated_at),
                "reference_url": r.reference_url, "raw_sha256": r.raw_sha256, "source_confidence": r.source_confidence,
                "error": r.error_message or (None if r.status == "ok" else "Donnée indisponible"),
                "findings": r.findings if kind == "technical" else None, "is_synthetic": r.is_synthetic,
            } for r in results],
        },
        "timeline": build_timeline(db, inv),
        "relations": {
            "provenance": "third_party",
            "disclaimer": "Une relation est une observation rapportée par une source ; elle ne prouve aucune causalité.",
            "items": [{
                "from": f"{r.from_kind}:{r.from_value}", "to": f"{r.to_kind}:{r.to_value}", "type": r.relation_type,
                "source": r.source_name, "temporality": r.temporality, "observed_at": iso(r.observed_at),
                "confidence": r.confidence, "evidence_id": f"R{r.evidence_result_id}" if r.evidence_result_id else None,
                "is_synthetic": r.is_synthetic,
            } for r in relations],
        },
        "correlation": {"provenance": "computed", **(inv.correlation or {})},
        "risk_assessment": {"provenance": "computed", **(inv.scoring or {})},
        "ai_analysis": {
            "provenance": "ai_generated",
            "provider": analysis.provider if analysis else None, "model": analysis.model if analysis else None,
            "status": analysis.status if analysis else "absent", "created_at": iso(analysis.created_at) if analysis else None,
            "input_sha256": analysis.input_sha256 if analysis else None,
            "validation_issues": analysis.validation_issues if analysis else [],
            "injection_flags": analysis.injection_flags if analysis else [],
            "output": analysis.output if analysis else None,
            "error": analysis.error_message if analysis else None,
        },
        "analyst_decisions": [{"ts": iso(n.created_at), "kind": n.kind, "author": n.user.username if n.user else None,
                               "content": n.content} for n in notes],
        "limitations": [
            "La géolocalisation IP est une estimation ; elle n'identifie ni une personne ni une position exacte.",
            "L'organisation enregistrée d'un bloc d'adresses n'est pas nécessairement l'utilisateur de l'adresse.",
            "L'absence de signalement ne prouve pas l'innocuité d'un indicateur.",
            "Les relations entre indicateurs sont des observations, non des preuves de causalité.",
            "Les conclusions générées par l'IA sont des aides à l'analyse soumises à validation humaine.",
            "L'empreinte SHA-256 du rapport permet de détecter une modification ultérieure ; elle ne constitue pas "
            "une signature horodatée qualifiée.",
        ] + (["RAPPORT CONTENANT DES DONNÉES DE DÉMONSTRATION SYNTHÉTIQUES."] if synthetic else []),
    }
    return data


def canonical_json(data: dict[str, Any]) -> bytes:
    return json.dumps(data, sort_keys=True, ensure_ascii=False, indent=2, default=str).encode("utf-8")


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()
